
$root=(Resolve-Path(Join-Path $PSScriptRoot '..')).Path;$desktop=[Environment]::GetFolderPath('Desktop');$launcher=Join-Path $env:LOCALAPPDATA 'EnglishAcquisitionAppLauncher';New-Item -ItemType Directory -Path $launcher -Force|Out-Null;Copy-Item (Join-Path $root 'scripts\launch_current.ps1') $launcher -Force;Copy-Item (Join-Path $root 'scripts\update_from_zip.ps1') $launcher -Force;$shell=New-Object -ComObject WScript.Shell;$icon=Join-Path $root 'windows\runner\resources\app_icon.ico';$a=$shell.CreateShortcut((Join-Path $desktop 'English Acquisition App.lnk'));$a.TargetPath='powershell.exe';$a.Arguments="-NoProfile -ExecutionPolicy Bypass -File `"$(Join-Path $launcher 'launch_current.ps1')`"";$a.WorkingDirectory=$root;if(Test-Path $icon){$a.IconLocation=$icon};$a.Save();$u=$shell.CreateShortcut((Join-Path $desktop 'Update English Acquisition App.lnk'));$u.TargetPath='powershell.exe';$u.Arguments="-NoLogo -NoProfile -NoExit -ExecutionPolicy Bypass -File `"$(Join-Path $launcher 'update_from_zip.ps1')`"";$u.WorkingDirectory=$root;if(Test-Path $icon){$u.IconLocation=$icon};$u.Save()
